// Источник: web-тест .qa/e2e/tests/guided-prayer/gp-06-share-button-main-prayers.spec.ts, план .qa/e2e/specs/guided-prayer.md, кейс .qa/tests/guided-prayer/GP-06-share-prayer-button.md
// Тикет #6a86f7df · 6a86f7df6f29cb4c367083d2 «עיצוב מוקאפ: תפילה מודרכת — קטע בתוך סדר התפילה». Опора: мокап S-17 (Figma 608:1726) — кнопка на каждом фрагменте основных молитв.
// Кнопку НЕ нажимать.
import { expect, $$, driver } from '@wdio/globals';
import { byText, byTextMatches, byLabel, byLabelStartsWith, tapText, expectVisibleText, pageCounter, scrollToText } from '../../helpers/ui.ts';
import { openPrayer, openRoute, hasDeepLinks, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const PRAYERS: Array<[key: string, title: string, total: number]> = [
  ['shacharit_ashkenaz', 'שחרית', 66],
  ['shacharit_sfarad', 'שחרית', 57],
  ['mincha_ashkenaz', 'מנחה', 8],
  ['mincha_sfarad', 'מנחה', 11],
  ['arvit_ashkenaz', 'ערבית', 15],
  ['arvit_sfarad', 'ערבית', 16],
];
/** Кнопки «שיתוף התפילה» на фрагменте (если ниже экрана — долистать до блока «האזן להקראה», над которым она стоит). */
async function shareButtons() {
  const first = await byLabel('שיתוף התפילה');
  if (!(await first.isDisplayed().catch(() => false))) await scrollToText('האזן להקראה').catch(() => {});
  const shown: WebdriverIO.Element[] = [];
  for (const el of await $$('~שיתוף התפילה')) if (await el.isDisplayed().catch(() => false)) shown.push(el);
  return shown;
}

/** Нажать «המשך»/«קודם» (если кнопка ниже экрана — долистать). */
async function tapNav(label: string) {
  const el = await byText(label);
  if (!(await el.isDisplayed().catch(() => false))) await scrollToText(label);
  await tapText(label);
}

async function counterIs(expected: string) {
  await driver.waitUntil(async () => (await pageCounter()) === expected, { timeoutMsg: `Счётчик не стал «${expected}»` });
}

/** Открыть молитву: אשכנז — из «תפילות»; ספרד — deep link или сменой нусаха в меню («ספרדי» → «החלף»). */
async function open(key: string, title: string) {
  const sfarad = key.endsWith('_sfarad');
  if (hasDeepLinks()) await openRoute(`/prayer/${key}`);
  else {
    await openPrayer(key.replace('_sfarad', '_ashkenaz'), title);
    if (sfarad) {
      await (await byLabelStartsWith('בחירת נוסח')).click();
      await tapText('ספרדי');
      const replace = await byText('החלף');
      if (await replace.isDisplayed().catch(() => false)) await replace.click();
    }
  }
  await expectVisibleText(`${title} (${sfarad ? 'ספרדי' : 'אשכנזי'})`);
  await (await byTextMatches('\\d+ מתוך \\d+')).waitForDisplayed();
}

/** Вернуть молитву в נוסח профиля (אשכנז) после ספרד, чтобы не влиять на другие тесты. */
async function backToAshkenaz(title: string) {
  if (hasDeepLinks()) return;
  await (await byLabelStartsWith('בחירת נוסח')).click();
  await tapText('אשכנזי');
  const replace = await byText('החלף');
  if (await replace.isDisplayed().catch(() => false)) await replace.click();
  await expectVisibleText(`${title} (אשכנזי)`);
}

describe('Молитва по шагам', () => {
  afterEach(async () => { await toHome(); });

  for (const [key, title, total] of PRAYERS) {
    it(`GP-06 Кнопка «שיתוף התפילה» на каждом фрагменте основных молитв — ${key} #6a86f7df @prod-safe`, async () => {
      // 1. Открыть молитву; «קודם» до «1 מתוך N» — N совпадает с ожидаемым.
      await open(key, title);
      expect(Number((await pageCounter()).split(' מתוך ')[1])).toBe(total);
      await goToPage(1, total);
      expect(await pageCounter()).toBe(`1 מתוך ${total}`);

      // 2. На каждом фрагменте — ровно одна видимая кнопка «שיתוף התפילה» (не нажимать); «המשך» до «N מתוך N».
      for (let i = 1; i <= total; i++) {
        await counterIs(`${i} מתוך ${total}`);
        expect((await shareButtons()).length).toBe(1);
        if (i < total) await tapNav('המשך');
      }

      if (key.endsWith('_sfarad')) await backToAshkenaz(title);
    });
  }
});
